function page(title, body, httpStatus = 200) {
  const html = `<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${escapeHtml(title)}</title>
<style>
  html { color-scheme: light; } body { font-family: Arial, sans-serif; font-size: 15px; color: #222; background: #fff; max-width: 820px; margin: 24px auto; padding: 0 16px; }
  label { display: block; margin: 12px 0 4px; font-weight: bold; }
  .choice { font-weight: normal; }
  input[type=text], textarea { width: 100%; padding: 6px; box-sizing: border-box; }
  .preview { border: 1px solid #ddd; padding: 12px; margin: 12px 0; }
  .notice { background: #fff4e5; padding: 10px 12px; }
  button { margin-top: 16px; padding: 8px 16px; font-size: 15px; }
</style></head><body>${body}</body></html>`;
  return [{ json: { html, http_status: httpStatus } }];
}

if (!quote) {
  return page(texts.page_invalid_link, `<p>${escapeHtml(texts.page_invalid_link)}</p>`, 404);
}

const title = fill(texts.page_title, { quote_id: quote.quote_id });
const ACTIONS = { PENDING_APPROVAL: ["APPROVE", "REJECT"], SEND_UNCERTAIN: ["MARK_SENT", "RESEND"] }[quote.status];
const preview = quote.customer_html
  ? `<p><b>${escapeHtml(quote.customer_subject)}</b> → ${escapeHtml(quote.customer_email)}</p><div class="preview">${quote.customer_html}</div>`
  : "";

if (!ACTIONS || !quote.customer_html) {
  return page(title, `<h2>${escapeHtml(title)}</h2><p>${escapeHtml(fill(texts.page_not_pending, { status: quote.status }))}</p>${preview}`);
}

const choices = ACTIONS.map((action, index) => `
  <label class="choice"><input type="radio" name="action" value="${action}" ${index === 0 ? "checked" : ""} required>
  ${escapeHtml(texts[`action_${action}`] ?? action)}</label>`).join("");

const body = `
  <h2>${escapeHtml(title)}</h2>
  ${quote.status === "SEND_UNCERTAIN" ? `<p class="notice">${escapeHtml(texts.uncertain_intro)}</p>` : `<p>${escapeHtml(texts.approval_intro)}</p>`}
  ${preview}
  <form method="post" action="">
    <input type="hidden" name="quote" value="${escapeHtml(quote.quote_id)}">
    <input type="hidden" name="token" value="${escapeHtml(query.token)}">
    ${choices}
    ${ACTIONS.includes("REJECT") ? `<label for="reason">${escapeHtml(texts.form_reason)}</label><textarea id="reason" name="reason" rows="3"></textarea>` : ""}
    <label for="decided_by">${escapeHtml(texts.form_decided_by)}</label>
    <input type="text" id="decided_by" name="decided_by" required>
    <button type="submit">${escapeHtml(texts.form_submit)}</button>
  </form>`;

return page(title, body);

// Convert the submitted form into the quote decision contract of the core; the core validates it.
const form = $input.first().json.body ?? {};
const reason = String(form.reason ?? "").trim();

return [
  {
    json: {
      token_check: { quote_id: String(form.quote ?? ""), token: String(form.token ?? ""), require_token: true },
      decision: {
        quote_id: String(form.quote ?? ""),
        token: String(form.token ?? ""),
        action: String(form.action ?? ""),
        decided_by: String(form.decided_by ?? "").trim(),
        ...(reason ? { reason } : {}),
      },
    },
  },
];

// Show the outcome of a submitted quote decision.
const { settings, quote } = $('Verify Quote Token').first().json;
const { decision } = $('Parse Quote Form').first().json;
const texts = settings?.review_texts?.[settings?.language]?.quote ?? settings?.review_texts?.en?.quote ?? {};

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}
function page(body, httpStatus) {
  const html = `<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<style>html { color-scheme: light; } body { font-family: Arial, sans-serif; font-size: 15px; color: #222; background: #fff; max-width: 640px; margin: 24px auto; padding: 0 16px; }</style>
</head><body>${body}</body></html>`;
  return [{ json: { html, http_status: httpStatus } }];
}

// The token proves the submitter received the approval email for exactly this quote.
if (!quote) {
  return page(`<p>${escapeHtml(texts.page_invalid_link)}</p>`, 404);
}

const { http_status: httpStatus, body } = $input.first().json;
if (httpStatus !== 200) {
  return page(
    `<p>${escapeHtml(texts.page_rejected)}</p><ul>${(body?.errors ?? []).map(e => `<li>${escapeHtml(e)}</li>`).join("")}</ul>`,
    httpStatus
  );
}
return page(`<p><b>${escapeHtml(texts[`result_${decision.action}`] ?? body.quote_status)}</b></p>`, 200);

const failure = $input.first().json;
if (!failure.ops_workflow_id) {
  return [];
}
return [{ json: { operation: "ops_event", workflow_id: failure.ops_workflow_id, payload: { event_type: "llm_failure", message: failure.last_error, reference: `inbound message ${failure.inbound_message_id}`, workflow_name: "P2 - Channel: Email" } } }];

const failure = $input.first().json;
if (!failure.ops_workflow_id) {
  return [];
}
return [{ json: { operation: "ops_event", workflow_id: failure.ops_workflow_id, payload: { event_type: "quote_delivery_failure", message: failure.last_error, reference: failure.quote_id, workflow_name: "P2 - Channel: Email" } } }];
